#!/usr/bin/env bash
# Regenerate crates/daemon/src/emoji_words.rs: the emoji picker's search words in the shell's
# other languages, from Unicode CLDR's annotations (and the derived ones: flags, skin tones,
# families), for the emoji of gemoji's table (`gen-emoji.sh`). One table a language: Spanish
# (es + es-419: Spain's and Latin America's words together), German, French, Italian,
# Portuguese (Brazil's, `pt`) and Portugal's (`pt-PT`). CLDR is under the Unicode License v3;
# the generated file carries that provenance in its header.
#
#   tools/gen-emoji/gen-emoji-words.sh [cldr-json tag] [gemoji ref]   # defaults below
set -euo pipefail
CLDR="${1:-47.0.0}"
REF="${2:-v4.1.0}"
REPO="$(cd "$(dirname "$0")/../.." && pwd)"
OUT="$REPO/crates/daemon/src/emoji_words.rs"
RAW="https://raw.githubusercontent.com/unicode-org/cldr-json/$CLDR/cldr-json"
JQ="${JQ:-jq}"
tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT
echo ">> fetching gemoji $REF and CLDR $CLDR" >&2
curl -fsSL "https://raw.githubusercontent.com/github/gemoji/$REF/db/emoji.json" -o "$tmp/gem.json"
fetch() { # <locale> -> its two annotation files, or nothing where CLDR has none
  curl -fsSL "$RAW/cldr-annotations-full/annotations/$1/annotations.json" -o "$tmp/$1.json" || rm -f "$tmp/$1.json"
  curl -fsSL "$RAW/cldr-annotations-derived-full/annotationsDerived/$1/annotations.json" -o "$tmp/$1-d.json" || rm -f "$tmp/$1-d.json"
}
{
  echo "//! The emoji's words in the shell's other languages — GENERATED, do not edit by hand."
  echo "//!"
  echo "//! Source: Unicode CLDR $CLDR annotations and derived annotations (Unicode License v3),"
  echo "//! for the emoji gemoji's table has; regenerated by \`tools/gen-emoji/gen-emoji-words.sh\`."
  echo "//! Each emoji's name and keywords, keyed by the emoji WITHOUT U+FE0F and sorted (found by"
  echo "//! halves). Spanish holds Spain's and Latin America's words together."
  # name | doc | the CLDR locales it is made of
  while IFS='|' read -r name doc locales; do
    files=()
    for l in $locales; do
      fetch "$l"
      for f in "$tmp/$l.json" "$tmp/$l-d.json"; do [ -f "$f" ] && files+=("$f"); done
    done
    "$JQ" -s '.' "${files[@]}" > "$tmp/notes.json"
    "$JQ" -n -r --arg name "$name" --arg doc "$doc" --slurpfile gem "$tmp/gem.json" \
      --slurpfile notes "$tmp/notes.json" -f "$(dirname "$0")/gen-emoji-words.jq"
  done <<'LANGS'
ES|Spanish: what an emoji is called and the words it goes by.|es es-419
DE|German.|de
FR|French.|fr
IT|Italian.|it
PT|Portuguese, Brazil's.|pt
PT_PT|Portuguese, Portugal's (its own words over Brazil's).|pt-PT pt
LANGS
} > "$OUT"
command -v rustfmt >/dev/null && rustfmt --edition 2021 "$OUT"
echo ">> wrote $OUT ($(grep -c '^    ("' "$OUT") rows)" >&2
